import { config } from '../config/environment.js';
import { AuditModel } from '../models/audit.model.js';

/**
 * Cloudflare Access Edge Boundary Middleware
 *
 * Verifies that requests entering via Cloudflare Access carry legitimate
 * edge identity headers:
 * - Cf-Access-Authenticated-User-Email: user's authenticated email at the edge
 * - Cf-Access-Jwt-Assertion: signed JWT assertion generated by Cloudflare Access
 *
 * Architecture Role:
 * - Edge Tier (Cloudflare Access): Verifies network/perimeter identity (mTLS / SSO / IdP).
 * - Origin Tier (Node.js Express): Verifies fine-grained authorization (JWT, RBAC, ownership).
 *
 * Behavior:
 * 1. If CLOUDFLARE_ACCESS_REQUIRED is enabled and headers are absent -> BLOCK (403 Forbidden).
 * 2. If edge headers are present -> Attaches req.cfAccess = { email, jwt }.
 * 3. In development or when disabled -> Bypasses cleanly to preserve local testing.
 */
export const verifyCloudflareAccess = async (req, res, next) => {
  try {
    const cfEmail = req.headers['cf-access-authenticated-user-email'];
    const cfJwt = req.headers['cf-access-jwt-assertion'];

    if (config.cloudflareAccessRequired) {
      if (!cfEmail || !cfJwt) {
        await AuditModel.logAccess({
          userId: null,
          endpoint: req.originalUrl,
          action: 'CLOUDFLARE_ACCESS_PERIMETER_CHECK',
          result: 'BLOCK',
          ipAddress: req.ip,
        });

        return res.status(403).json({
          success: false,
          error: 'Forbidden',
          message:
            'Access denied: Request must originate through an authenticated Cloudflare Access session.',
        });
      }
    }

    if (cfEmail) {
      req.cfAccess = {
        email: cfEmail,
        jwtAssertion: cfJwt || null,
      };
    }

    next();
  } catch (error) {
    next(error);
  }
};
